def devig(kurs_a, kurs_b):
    """Kursy amerykanskie jednej ksiazki -> p_a bez marzy."""
    i = lambda c: 100 / (c + 100) if c > 0 else -c / (-c + 100)
    return i(kurs_a) / (i(kurs_a) + i(kurs_b))


def _biny(v, kraw, wagi=None):
    v = np.asarray(v, dtype=float)
    wagi = np.ones(len(v)) / len(v) if wagi is None else wagi
    out, lo = [], -np.inf
    for k in kraw:
        out.append(float(wagi[(v > lo) & (v <= k)].sum()))
        lo = k
    out.append(float(wagi[v > kraw[-1]].sum()))
    return out


def _dnp(p, kraw, status):
    d = DANE["dnp"][status]
    z = np.array(_biny([0.0], kraw))
    return list((1 - d) * np.asarray(p) + d * z)


def _pasmo(linia):
    return str(int(min(57, max(36, round(linia)))))


def total(linia, p_over, kraw):
    """Linia + empiryczna reszta meczow o podobnej linii (+-4 pkt)."""
    sr = linia + DANE["sd_total"] * (p_over - 0.5) * math.sqrt(2 * math.pi)
    return _biny(sr + np.array(DANE["reszta_total"][_pasmo(linia)]), kraw)


def _mediana(linie, skala):
    return sum((l + (p - 0.5) * skala) * n for l, p, n in linie) / sum(n for _, _, n in linie)


def _ksztalt(klasa, med, kraw, sigma, zaokr=False):
    w = np.array(DANE["ksztalty"][klasa])
    pb = np.zeros(len(kraw) + 1)
    for m, waga in ((1 - sigma, .25), (1.0, .5), (1 + sigma, .25)):
        v = med / float(np.median(w)) * m * w
        pb += waga * np.array(_biny(np.round(v) if zaokr else v, kraw))
    return pb


def jardy(linie, kraw, klasa, status="brak_full"):
    """Klasy: wr65 (WR sr>=65), wr30_55 (WR sr 30-55), rb75 (RB sr>=75), rb_klasa (RB nizej). Sigma 0,10."""
    skala = 110.0 if klasa.startswith("wr") else 100.0
    return _dnp(_ksztalt(klasa, _mediana(linie, skala), kraw, 0.10), kraw, status)


def qb_celne(linie, kraw, status="brak_full"):
    p = _ksztalt("qb_celne", _mediana(linie, 13.0), kraw, 0.06, zaokr=True)
    p = (1 - P_KRZYWO) * p + P_KRZYWO * np.array(_biny([3., 6., 9., 12.], kraw))
    return _dnp(p, kraw, status)


def _nb(mean, vm, kmax=40):
    r = mean / (vm - 1)
    q = 1 / vm
    p = [q ** r]
    for k in range(1, kmax + 1):
        p.append(p[-1] * (k - 1 + r) / k * (1 - q))
    return np.array(p)


def odbiory(linie, kraw, status="brak_full"):
    """NB dopasowana do linii. vm wg sredniej: <6,5 -> 1,121; 6,5-7 -> 1,161; >=7 -> 1,152. Sigma 0,10."""
    pts = [(int(math.ceil(l)), p) for l, p, n in linie]
    blad = lambda m, vm: sum((_nb(m, vm)[k:].sum() - p) ** 2 for k, p in pts)
    siatka_m = np.arange(1.0, 14.0, 0.01)
    vm = DANE["vm_odbiory"]["rec_vm_6.5_8.5"]
    m0 = min(siatka_m, key=lambda m: blad(m, vm))
    vm = DANE["vm_odbiory"]["rec_vm_5.5_7.0" if m0 < 6.5 else ("rec_vm_6.5_8.5" if m0 < 8.5 else "rec_vm_7.0_9.0")]
    m0 = min(siatka_m, key=lambda m: blad(m, vm))
    pm = sum(w * _nb(m0 * x, vm) for x, w in ((.9, .25), (1., .5), (1.1, .25)))
    p, lo = [], -1
    for k in kraw:
        p.append(float(pm[lo + 1:k + 1].sum()))
        lo = k
    p.append(float(pm[kraw[-1] + 1:].sum()))
    return _dnp(p, kraw, status)


def td_ktorys(gracze, total_meczu, suma_surowych):
    """Yes/No 'ktorys z graczy zdobedzie TD'. gracze = [(p_surowe_z_kursu, status)]. suma_surowych = suma p WSZYSTKICH graczy
    ataku obu druzyn z >= 3 ksiazek, bez zakladow druzynowych. Mnoznik = (0,0987*total-0,410)/suma."""
    mn = (0.0987 * total_meczu - 0.410) / suma_surowych
    assert 0.55 < mn < 0.95, "mnoznik %.3f poza zakresem - sprawdzic, czy lista graczy jest pelna" % mn
    pno = 1.0
    for p, st in gracze:
        pno *= 1 - p * mn * (1 - DANE["dnp"][st])
    return [1 - pno, pno]


def fg(total_meczu, spread, fg_a, fg_b, kraw):
    """Liczba FG, BRAK RYNKU: empiria pasa linii przechylona do regresji. fg_a, fg_b = trafione FG/mecz druzyn w tym sezonie."""
    b = DANE["fg_beta"]
    d = DANE["fg_druzyny"]
    cel = b[0] + b[1] * total_meczu + b[2] * abs(spread) + b[3] * 6 + d["nachylenie"] * (fg_a + fg_b - d["srednia"])
    hist, ks = np.array(DANE["fg_hist"][_pasmo(total_meczu)]), np.arange(15)
    lo, hi = -1.0, 1.0
    for _ in range(200):
        th = (lo + hi) / 2
        w = hist * np.exp(th * ks)
        w = w / w.sum()
        lo, hi = (th, hi) if (w * ks).sum() < cel else (lo, th)
    return _biny(ks, kraw, w)


def _kolejnosc(A, seed=1):
    """Sasiednie wpisy jak najbardziej rozne (Warnsdorff). Sklad bez zmian."""
    n = len(A)
    R = (A[:, None, :] != A[None, :, :]).sum(axis=2)
    rng = np.random.default_rng(seed)
    for d in range(A.shape[1], 0, -1):
        G = R >= d
        np.fill_diagonal(G, False)
        for _ in range(300):
            droga, wolne = [int(rng.integers(n))], np.ones(n, bool)
            wolne[droga[0]] = False
            while len(droga) < n:
                kand = np.where(G[droga[-1]] & wolne)[0]
                if not len(kand):
                    break
                st = (G[kand][:, wolne]).sum(axis=1) + rng.random(len(kand)) / 2
                droga.append(int(kand[st.argmin()]))
                wolne[droga[-1]] = False
            if len(droga) == n:
                return droga, d
    return list(range(n)), 0


def _po_kolei(a, b, lista):
    i, j = lista.index(a), lista.index(b)
    if abs(i - j) == 1:
        return True
    return a.isdigit() and b.isdigit() and abs(int(a) - int(b)) == 1


KATALOG = [  # zaleznosci w jednym meczu, alpha zmierzone poza proba na slate'ach 09.09-27.10 (nfl-zrodla-i-pomiary)
    (("pkt", "fg", "td"), 1.0), (("pkt", "fg"), 1.0), (("pkt", "td"), 1.0), (("fg", "td"), 1.0),
    (("wynik", "rb_und"), 1.0), (("wynik", "rb_und_yds"), 1.0), (("wynik", "rb_fav_yds"), 1.0), (("wynik", "qb_fav_cmp"), 1.0),
    (("pkt", "qb_fav"), 0.75), (("qb_fav", "wr_fav"), 0.75), (("qb_fav_cmp", "wr_fav_yds"), 0.6), (("qb_fav_cmp", "wr_fav_yds65"), 0.6),
    (("pkt", "qb_und"), 0.75), (("pkt", "wr_fav"), 1.0),
]
HIST_URL = "https://raw.githubusercontent.com/torpedomain-bit/pickems-dane/main/_cechy1030.csv"


def historia(sciezka=None):
    """Mecze 2015-25 (kolumny wzgledne do sredniej sezonu gracza). Pobiera raz z gista."""
    import csv, os, urllib.request
    sciezka = sciezka or "/tmp/_cechy.csv"
    if not os.path.exists(sciezka):
        urllib.request.urlretrieve(HIST_URL, sciezka)
    w = list(csv.DictReader(open(sciezka, encoding="utf-8")))
    assert len(w) > 2500, len(w)
    return w


def _wartosc(r, kol):
    if kol == "wynik":
        a, b = float(r["fav_pkt"]), float(r["und_pkt"])
        return "fav" if a > b else ("und" if b > a else "tie")
    x = r.get(kol, "")
    return float(x) if x not in ("", "nan") else None


def jeden_mecz(pytania, role, hist=None):
    """Log-laczny rozklad slate'u z JEDNEGO meczu: iloczyn marginali x lifty z KATALOGU, IPF wraca na marginalia.
    role = {indeks_pytania: (kolumna, spec)}: ("pkt"|"fg"|"td", kraw); ("wynik", {"fav":i,"und":j,"tie":k});
    ("qb_fav"|"wr_fav"|"rb_und"|..., (kraw, srednia_gracza)). Pytania bez roli (tackle itp.) = niezalezne."""
    hist = hist or historia()
    ps = [np.array(p, dtype=float) / sum(p) for _, _, p in pytania]
    ksz = [len(p) for p in ps]
    P = np.ones(ksz)
    for i, p in enumerate(ps):
        sh = [1] * len(ksz)
        sh[i] = len(p)
        P = P * p.reshape(sh)
    kol2q = {k: q for q, (k, _) in role.items()}

    def bin_(q, r):
        k, spec = role[q]
        v = _wartosc(r, k)
        if v is None:
            return None
        if k == "wynik":
            return spec[v]
        kr, sr = spec if isinstance(spec, tuple) else (spec, 1.0)
        return int(np.searchsorted(kr, v * sr, side="left"))
    uzyte = set()
    for czyn, alfa in KATALOG:
        if not all(c in kol2q for c in czyn) or any(set(czyn) <= u for u in uzyte):
            continue
        uzyte.add(frozenset(czyn))
        qs = [kol2q[c] for c in czyn]
        obs = np.full([ksz[q] for q in qs], 0.5)
        for r in hist:
            b = [bin_(q, r) for q in qs]
            if None not in b:
                obs[tuple(b)] += 1
        pr = obs / obs.sum()
        ex = np.ones(pr.shape)
        for i in range(len(qs)):
            sh = [1] * len(qs)
            sh[i] = pr.shape[i]
            ex = ex * pr.sum(axis=tuple(j for j in range(len(qs)) if j != i)).reshape(sh)
        lift = (pr / ex) ** alfa
        if "wynik" in czyn and "tie" in role[kol2q["wynik"]][1]:   # remis meczu: za malo historii
            idx = [slice(None)] * len(qs)
            idx[czyn.index("wynik")] = role[kol2q["wynik"]][1]["tie"]
            lift[tuple(idx)] = 1.0
        sh = [1] * len(ksz)
        for q, d in zip(qs, lift.shape):
            sh[q] = d
        os_ = np.argsort(qs)
        P = P * np.transpose(lift, os_).reshape(sh)
    for _ in range(100):
        for i, p in enumerate(ps):
            os_ = tuple(j for j in range(len(ksz)) if j != i)
            m = P.sum(axis=os_)
            sh = [1] * len(ksz)
            sh[i] = len(p)
            P = P * (p / np.maximum(m, 1e-15)).reshape(sh)
    print("zaleznosci:", [sorted(u) for u in uzyte])
    return np.log(np.maximum(P, 1e-300)).ravel()


def siatka(pytania, wejscia, cap=None, L=None):
    """pytania = [(nazwa, [etykiety binow], [p])] Q1..Q8 w kolejnosci z quizu. Top-N po iloczynie, N = liczba wejsc.
    L = wynik jeden_mecz(...) przy slate z jednego meczu."""
    n = len(wejscia)
    for nazwa, et, p in pytania:
        assert len(et) == len(p), nazwa
        assert abs(sum(p) - 1) < 0.02, (nazwa, sum(p))
    ps = [np.array(p) / sum(p) for _, _, p in pytania]
    if L is None:
        L = np.zeros(1)
        for p in ps:
            L = (L[:, None] + np.log(np.maximum(p, 1e-12))).ravel()
    ksz = [len(p) for p in ps]
    uzyte = [np.zeros(k, int) for k in ksz]
    wybor, P = [], 0.0
    cap = cap or n
    for i in np.argsort(-L):
        w = np.unravel_index(int(i), ksz)
        if all(uzyte[q][w[q]] < cap for q in range(len(ksz))):
            wybor.append([int(x) for x in w])
            P += float(math.exp(L[i]))
            for q in range(len(ksz)):
                uzyte[q][w[q]] += 1
            if len(wybor) == n:
                break
    A = np.array(wybor)
    assert len({tuple(r) for r in wybor}) == n, "duplikaty wpisow"
    droga, d = _kolejnosc(A)
    rng = np.random.default_rng()
    for _ in range(10000):
        pw = [wejscia[i] for i in rng.permutation(n)]
        if not any(_po_kolei(pw[i], pw[i + 1], wejscia) for i in range(n - 1)):
            break
    wpisy = [(pw[i], [pytania[q][1][A[j][q]] for q in range(len(ksz))]) for i, j in enumerate(droga)]
    return {"wpisy": wpisy, "P8": P, "pytania": pytania, "min_sasiad": d, "uzyte": uzyte}


def wypisz(w):
    print("P(8/8) = %.3f %%, sasiedzi roznia sie min. o %d z 8" % (100 * w["P8"], w["min_sasiad"]))
    for (nazwa, et, p), u in zip(w["pytania"], w["uzyte"]):
        print(nazwa, " ".join("%s %.1f%% x%d" % (e, 100 * x, k) for e, x, k in zip(et, p, u)))
    print("Wejscie | " + " | ".join(x[0] for x in w["pytania"]))
    for we, od in w["wpisy"]:
        print(we + " | " + " | ".join(od))
